#!/usr/bin/env python3
"""Builds shared/src/commonMain/kotlin/com/example/data/model/RegionsData.kt (generated, do not edit): every country's first-level areas (states, governorates,
provinces), used by registration step 2 (country + area dropdowns).

Source: npm package country-region-data 3.1.0 (MIT, (c) 2022 Benjamin Keen), its data.json. Run:
    npm pack country-region-data@3.1.0 && tar xzf country-region-data-3.1.0.tgz
    python3 scripts/i18n/build_regions.py package/data.json
Areas are the English names; OVERRIDES fixes names the source gives in another language, LOCAL adds names in Arabic.
"""
import json
import os
import sys

OUT = os.path.join(os.path.dirname(__file__), "../../shared/src/commonMain/kotlin/com/example/data/model/RegionsData.kt")

# The source names Lebanon's governorates in French.
OVERRIDES = {
    "LB": ["Akkar", "Baalbek-Hermel", "Beirut", "Beqaa", "Mount Lebanon", "Nabatieh", "North Lebanon", "South Lebanon"],
}
LOCAL = {
    "ar": {
        "LB": {"Akkar": "عكار", "Baalbek-Hermel": "بعلبك الهرمل", "Beirut": "بيروت", "Beqaa": "البقاع",
               "Mount Lebanon": "جبل لبنان", "Nabatieh": "النبطية", "North Lebanon": "الشمال", "South Lebanon": "الجنوب"},
    },
}


def main(src):
    data = json.load(open(src, encoding="utf-8"))
    areas = {c["countryShortCode"]: sorted({r["name"] for r in c["regions"]}) for c in data}
    areas.update(OVERRIDES)
    def lit(text):
        return '"' + text.replace("\\", "\\\\").replace('"', '\\"').replace("$", "\\$") + '"'
    lines = ["// GENERATED by scripts/i18n/build_regions.py from country-region-data 3.1.0 (MIT, (c) 2022 Benjamin Keen). Do not edit.",
             "package com.example.data.model", "",
             "/** First-level areas of a country (ISO 3166-1 alpha-2), English names joined by '|'; null when none are listed. */",
             "internal fun regionsRaw(isoCode: String): String? = when (isoCode) {"]
    for code, names in sorted(areas.items()):
        if names:
            lines.append(f"    {lit(code)} -> {lit('|'.join(names))}")
    lines += ["    else -> null", "}", "",
              "/** Area names in another language: language -> ISO code -> English name -> local name. */",
              "internal val regionsLocal: Map<String, Map<String, Map<String, String>>> = mapOf("]
    for lang, per in LOCAL.items():
        inner = ", ".join(f"{lit(c)} to mapOf(" + ", ".join(f"{lit(k)} to {lit(v)}" for k, v in m.items()) + ")" for c, m in per.items())
        lines.append(f"    {lit(lang)} to mapOf({inner}),")
    lines += [")", ""]
    with open(OUT, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))
    print(f"wrote {os.path.relpath(OUT)}: {len(areas)} countries, {sum(map(len, areas.values()))} areas")


if __name__ == "__main__":
    main(sys.argv[1])
